// Snowflakes are generated by sunflake with its default epoch (2022-01-01T00:00:00Z):
//  the upper bits hold milliseconds since that epoch.
const EPOCH = 1_640_995_200_000n;

/** Creation time encoded in a Kontestis snowflake id. */
export const snowflakeDate = (id: bigint) => new Date(Number((BigInt(id) >> 22n) + EPOCH));
